"""Campaign compilation, strict witness recovery, and offline replay certificates."""
from .ast import (Alias, Bool, Enum, Evaluator, ExpressionCompiler, Parameter,
                  Struct, TypeRegistry)
from .composer import DependencyGraph
from .oracles import LayoutBuilder, ResultReader, TypeCollector
from .run import Corpus
from .state import StateMachine
from .wire import InvalidTest, decode


class Module:
    def __init__(self, source, registry, expressions):
        self.name = source["name"]
        self.inputs = [Parameter(name, registry[type_name]) for name, type_name in source["params"]]
        name, type_name = source["result"]
        self.result = Parameter(name, registry[type_name])
        self.scope = {parameter.name: parameter.type for parameter in self.inputs}
        self.predicate = expressions.compile(source["requires"], self.scope)
        self.pipes = []


class Entry:
    def __init__(self, name, modules, graph, expressions, machine):
        self.module = module = modules[name]
        order = graph.compile_order(name)
        types = []
        collector = TypeCollector(types)
        for dependency in order:
            helper = modules[dependency]
            for parameter in helper.inputs + [helper.result]:
                collector.visit(parameter.type)
        declarations = [node.name for node in types if isinstance(node, (Enum, Struct, Alias))]

        layout = LayoutBuilder()
        for parameter in module.inputs + [module.result]:
            layout.visit(parameter.type, [parameter.name])
        self.flag = None
        if module.pipes:
            self.flag = layout.reserve()
            layout.expected[self.flag] = 1
        self.expected = layout.expected
        self.plan = {"entry": name, "modules": order, "types": declarations,
                     "slots": layout.slots, "flag": self.flag, "variables": layout.number}

        # Compile applications, not merely filter names: the same filter may
        # appear through distinct paths and with different composed bindings.
        # Calls affect the plan only and never enter this predicate traversal.
        self.applications = []
        pending = [(module, {parameter.name: parameter.name for parameter in module.inputs})]
        while pending:
            target, binding = pending.pop()
            for filter_name, local_binding in reversed(target.pipes):
                bound = {parameter: binding[value] for parameter, value in local_binding.items()}
                filter_module = modules[filter_name]
                self.applications.append((filter_module.predicate, bound))
                pending.append((filter_module, bound))

        self.guards = [] if machine is None else [
            expressions.compile(guard, module.scope) for guard in machine.guards]

    def recover(self, payload):
        assignment = decode(payload, self.expected)
        reader = ResultReader(assignment)
        inputs = {parameter.name: reader.visit(parameter.type) for parameter in self.module.inputs}
        result = reader.visit(self.module.result.type)
        flag = reader.visit(Bool()) if self.flag is not None else None
        return inputs, result, flag

    def accepts(self, inputs, flag):
        pipes_accept = True
        for predicate, binding in self.applications:
            environment = {name: inputs[source] for name, source in binding.items()}
            if not Evaluator(environment).visit(predicate):
                pipes_accept = False
                break
        if self.flag is not None and flag != (not pipes_accept):
            raise InvalidTest("bad_input attestation")
        return pipes_accept and bool(Evaluator(inputs).visit(self.module.predicate))


def execute(campaign):
    registry = TypeRegistry(campaign["types"])
    expressions = ExpressionCompiler(registry)
    modules = {item["name"]: Module(item, registry, expressions) for item in campaign["modules"]}
    graph = DependencyGraph()
    for name in modules:
        graph.add_node(name)
    for caller, callee in campaign["calls"]:
        graph.add_edge(callee, caller)
    for pipe in campaign["pipes"]:
        target, filter_name = pipe["target"], pipe["filter"]
        modules[target].pipes.append((filter_name, pipe["bind"]))
        graph.Pipe(target, filter_name)

    machine = StateMachine(campaign["machine"]) if campaign["machine"] is not None else None
    entries = {name: Entry(name, modules, graph, expressions, machine) for name in campaign["entries"]}
    records = []
    corpus = Corpus()
    for witness, run in enumerate(campaign["runs"]):
        entry = entries[run["entry"]]
        try:
            inputs, result, flag = entry.recover(run["ktest"])
            accepted = entry.accepts(inputs, flag)
        except InvalidTest:
            records.append({"status": "INVALID_TEST"})
            continue
        if not accepted:
            records.append({"status": "FILTERED"})
            continue
        if machine is None:
            cost, commands = 0, []
        else:
            evaluator = Evaluator(inputs)
            preparation = machine.prepare(inputs[machine.state_param],
                                          lambda index: evaluator.visit(entry.guards[index]))
            if preparation is None:
                records.append({"status": "UNREACHABLE"})
                continue
            cost, commands = preparation
            commands.append(inputs[machine.message_param])
        records.append(corpus.add(run["entry"], inputs, cost, commands, witness, result))
    return {"plans": [entry.plan for entry in entries.values()], "records": records,
            "corpus": corpus.entries}
